// SQL триггер для демонстрации:
// CREATE OR REPLACE FUNCTION notify_outbox_event() RETURNS TRIGGER AS $$
// BEGIN
//     PERFORM pg_notify('outbox_channel', NEW.id::text);
//     RETURN NEW;
// END;
// $$ LANGUAGE plpgsql;
// CREATE TRIGGER trg_outbox_notify AFTER INSERT ON outbox_events
// FOR EACH ROW EXECUTE FUNCTION notify_outbox_event();

type NotificationChannel struct {
	ch chan string
	mu sync.Mutex
}

func NewNotificationChannel() *NotificationChannel {
	return &NotificationChannel{
		ch: make(chan string, 100),
	}
}

func (n *NotificationChannel) Notify(eventID string) {
	n.ch <- eventID
}

func (n *NotificationChannel) Listen() <-chan string {
	return n.ch
}

type PushRelayWorker struct {
	notifyChan *NotificationChannel
}

func NewPushRelayWorker(nc *NotificationChannel) *PushRelayWorker {
	return &PushRelayWorker{notifyChan: nc}
}

func (w *PushRelayWorker) Run(ctx context.Context) {
	fmt.Println("[Worker] Subscribed to PostgreSQL channel 'outbox_channel'. Waiting for Push events...")

	// Резервный таймер безопасности на случай потери нотификации при сбое сети
	fallbackTicker := time.NewTicker(5 * time.Second)
	defer fallbackTicker.Stop()

	for {
		select {
		case <-ctx.Done():
			fmt.Println("[Worker] Shutting down reactive relay.")
			return

		case eventID := <-w.notifyChan.Listen():
			start := time.Now()
			fmt.Printf("[Worker NOTIFY WAKEUP] Received push notification for event %s! Immediate dispatch.\n", eventID)
			// Имитация быстрой выборки и отправки
			time.Sleep(2 * time.Millisecond)
			fmt.Printf(" -> Event %s sent to Kafka in %v (Zero idle polling latency!)\n", eventID, time.Since(start))

		case <-fallbackTicker.C:
			fmt.Println("[Worker Fallback Poll] Safe periodic check for orphaned records...")
		}
	}
}

func main() {
	notifyChan := NewNotificationChannel()
	worker := NewPushRelayWorker(notifyChan)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go worker.Run(ctx)

	time.Sleep(50 * time.Millisecond)

	fmt.Println("\n=== Business Service inserts new order into DB with trigger NOTIFY ===")
	notifyChan.Notify("evt-push-1001")

	time.Sleep(50 * time.Millisecond)

	fmt.Println("\n=== Business Service inserts second order ===")
	notifyChan.Notify("evt-push-1002")

	time.Sleep(100 * time.Millisecond)
	cancel()
	time.Sleep(20 * time.Millisecond)
}

package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

type InboxEntry struct {
	EventID     string
	ProcessedAt time.Time
}

type InboxStore struct {
	mu      sync.Mutex
	entries map[string]InboxEntry
}

func NewInboxStore() *InboxStore {
	return &InboxStore{
		entries: make(map[string]InboxEntry),
	}
}

func (s *InboxStore) PruneOldRecords(olderThan time.Duration, limit int) int {
	s.mu.Lock()
	defer s.mu.Unlock()

	threshold := time.Now().Add(-olderThan)
	deleted := 0

	for id, entry := range s.entries {
		if entry.ProcessedAt.Before(threshold) {
			delete(s.entries, id)
			deleted++
			if deleted >= limit {
				break
			}
		}
	}

	return deleted
}

func (s *InboxStore) Count() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.entries)
}

type PruningDaemon struct {
	store        *InboxStore
	retention    time.Duration
	pruneTicker  *time.Ticker
	stopChan     chan struct{}
}

func NewPruningDaemon(store *InboxStore, retention time.Duration, interval time.Duration) *PruningDaemon {
	return &PruningDaemon{
		store:       store,
		retention:   retention,
		pruneTicker: time.NewTicker(interval),
		stopChan:    make(chan struct{}),
	}
}

func (d *PruningDaemon) Start(ctx context.Context) {
	go func() {
		fmt.Printf("[Pruning Daemon] Started. Retention window: %v\n", d.retention)
		for {
			select {
			case <-ctx.Done():
				return
			case <-d.stopChan:
				return
			case <-d.pruneTicker.C:
				totalDeleted := 0
				for {
					// Chunked deletion (пачками по 500 записей)
					n := d.store.PruneOldRecords(d.retention, 500)
					totalDeleted += n
					if n == 0 {
						break
					}
				}
				if totalDeleted > 0 {
					fmt.Printf("[Pruning Daemon] Pruned %d expired entries. Remaining active inbox size: %d\n",
						totalDeleted, d.store.Count())
				}
			}
		}
	}()
}

func (d *PruningDaemon) Stop() {
	d.pruneTicker.Stop()
	close(d.stopChan)
}

func main() {
	store := NewInboxStore()
	now := time.Now()

	// Добавим старые записи (возраст 8 дней)
	for i := 1; i <= 3; i++ {
		id := fmt.Sprintf("old-msg-%d", i)
		store.entries[id] = InboxEntry{
			EventID:     id,
			ProcessedAt: now.Add(-8 * 24 * time.Hour),
		}
	}

	// Добавим свежие записи (возраст 1 час)
	for i := 1; i <= 2; i++ {
		id := fmt.Sprintf("fresh-msg-%d", i)
		store.entries[id] = InboxEntry{
			EventID:     id,
			ProcessedAt: now.Add(-1 * time.Hour),
		}
	}

	fmt.Printf("Initial total inbox records: %d\n", store.Count())

	// Запуск демона с retention = 7 дней и тикером 20мс для теста
	daemon := NewPruningDaemon(store, 7*24*time.Hour, 20*time.Millisecond)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	daemon.Start(ctx)

	time.Sleep(50 * time.Millisecond)
	daemon.Stop()

	fmt.Printf("Final verified inbox records: %d (Only fresh messages preserved)\n", store.Count())
}

package main

import (
	"context"
	"fmt"
	"sync"
)

type ChainMessage struct {
	EventID       string
	CorrelationID string
	Topic         string
	Payload       string
}

type SimpleBroker struct {
	mu     sync.Mutex
	queues map[string][]ChainMessage
}

func NewSimpleBroker() *SimpleBroker {
	return &SimpleBroker{queues: make(map[string][]ChainMessage)}
}

func (b *SimpleBroker) Send(msg ChainMessage) {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.queues[msg.Topic] = append(b.queues[msg.Topic], msg)
}

func (b *SimpleBroker) Receive(topic string) []ChainMessage {
	b.mu.Lock()
	defer b.mu.Unlock()
	msgs := b.queues[topic]
	b.queues[topic] = nil
	return msgs
}

// Service A (Order Service): Outbox
type ServiceA struct {
	broker *SimpleBroker
}

func (a *ServiceA) CreateOrder(orderID, correlationID string) {
	fmt.Printf("[Service A - Orders] Transaction: Insert Order %s + Outbox Event (Correlation: %s)\n",
		orderID, correlationID)
	// Outbox Relay отправляет в брокер
	a.broker.Send(ChainMessage{
		EventID:       "evt-order-1",
		CorrelationID: correlationID,
		Topic:         "orders.created",
		Payload:       fmt.Sprintf(`{"order_id": "%s"}`, orderID),
	})
}

// Service B (Warehouse Service): Inbox + Business + Outbox
type ServiceB struct {
	broker *SimpleBroker
	inbox  map[string]bool
	stock  map[string]int
}

func NewServiceB(b *SimpleBroker) *ServiceB {
	return &ServiceB{
		broker: b,
		inbox:  make(map[string]bool),
		stock:  map[string]int{"item-1": 100},
	}
}

func (s *ServiceB) ProcessOrders() {
	msgs := s.broker.Receive("orders.created")
	for _, msg := range msgs {
		fmt.Printf("[Service B - Warehouse] Received %s (Correlation: %s)\n", msg.EventID, msg.CorrelationID)

		// Единая транзакция: Inbox + Stock + Outbox
		if s.inbox[msg.EventID] {
			fmt.Println(" -> [Duplicate Ignored] Already processed.")
			continue
		}
		s.inbox[msg.EventID] = true
		s.stock["item-1"] -= 1

		// Исходящее событие в Outbox
		outEvent := ChainMessage{
			EventID:       "evt-stock-res-1",
			CorrelationID: msg.CorrelationID, // Сквозная трассировка сохраняется
			Topic:         "inventory.reserved",
			Payload:       `{"order_id": "ord-99", "status": "RESERVED"}`,
		}
		s.broker.Send(outEvent)
		fmt.Printf(" -> [Service B Committed] Reserved stock and sent outbox event %s\n", outEvent.EventID)
	}
}

// Service C (Delivery Service): Inbox
type ServiceC struct {
	broker *SimpleBroker
	inbox  map[string]bool
}

func NewServiceC(b *SimpleBroker) *ServiceC {
	return &ServiceC{broker: b, inbox: make(map[string]bool)}
}

func (s *ServiceC) ProcessDelivery() {
	msgs := s.broker.Receive("inventory.reserved")
	for _, msg := range msgs {
		fmt.Printf("[Service C - Delivery] Received %s (Correlation: %s)\n", msg.EventID, msg.CorrelationID)
		if s.inbox[msg.EventID] {
			fmt.Println(" -> [Duplicate Ignored] Already scheduled delivery.")
			continue
		}
		s.inbox[msg.EventID] = true
		fmt.Printf(" -> [Service C Committed] Scheduled courier delivery for Correlation: %s\n", msg.CorrelationID)
	}
}

func main() {
	broker := NewSimpleBroker()
	srvA := &ServiceA{broker: broker}
	srvB := NewServiceB(broker)
	srvC := NewServiceC(broker)

	_ = context.Background()
	corrID := "trace-uuid-abcdef-12345"

	fmt.Println("=== 1. Service A triggers Order Creation ===")
	srvA.CreateOrder("ord-99", corrID)

	fmt.Println("\n=== 2. Service B processes Order and emits Stock Reserved ===")
	srvB.ProcessOrders()

	fmt.Println("\n=== 3. Service C processes Stock Reserved and Schedules Delivery ===")
	srvC.ProcessDelivery()

	fmt.Println("\n=== 4. End-to-End Trace Verification ===")
	fmt.Printf("Correlation ID '%s' successfully propagated across all 3 services.\n", corrID)
}

